51	async function buildTree(repoDir: string, entries: Record<string, FileNode | DirNode>): Promise<string> {
52	  const lines: string[] = [];
53	  for (const [name, node] of Object.entries(entries)) {
54	    if (node.kind === 'blob') {
55	      lines.push(`100644 blob ${node.sha}\t${name}`);
56	    } else {
57	      const sha = await buildTree(repoDir, node.entries);
58	      lines.push(`040000 tree ${sha}\t${name}`);
59	    }
60	  }
61	  return run(repoDir, ['mktree'], lines.join('\n') + '\n');
