66	    execFile(
67	      'git',
68	      ['commit-tree', treeSha, '-m', message],
69	      {
70	        cwd: repoDir,
71	        env: {
72	          ...process.env,
73	          GIT_AUTHOR_NAME: 'fixture',
74	          GIT_AUTHOR_EMAIL: 'fixture@example.com',
75	          GIT_COMMITTER_NAME: 'fixture',
76	          GIT_COMMITTER_EMAIL: 'fixture@example.com',
77	        },
78	      },
