87	async function buildSessionNode(repoDir: string, session: FixtureSession): Promise<DirNode> {
88	  const metadata = {
89	    session_id: session.sessionId,
90	    created_at: session.createdAt,
91	    agent: 'claude-code',
92	    model: 'claude-sonnet-4.6',
93	    branch: 'main',
94	    files_touched: [],
95	    token_usage: { input_tokens: 100, output_tokens: 50, cache_read_tokens: 0, cache_creation_tokens: 0 },
96	    session_metrics: { turn_count: session.lines.length },
97	  };
98	  const transcript = session.lines.map((l) => JSON.stringify(l)).join('\n');
99	  const [metaSha, promptSha, transcriptSha, fullSha] = await Promise.all([
100	    hashBlob(repoDir, JSON.stringify(metadata, null, 2)),
101	    hashBlob(repoDir, ''),
102	    hashBlob(repoDir, transcript),
103	    hashBlob(repoDir, transcript),
104	  ]);
105	  return {
106	    kind: 'tree',
107	    entries: {
108	      'metadata.json': { kind: 'blob', sha: metaSha },
109	      'prompt.txt': { kind: 'blob', sha: promptSha },
110	      'transcript.jsonl': { kind: 'blob', sha: transcriptSha },
111	      'full.jsonl': { kind: 'blob', sha: fullSha },
112	    },
113	  };
114	}
