116	async function buildCheckpointNode(repoDir: string, checkpoint: FixtureCheckpoint): Promise<DirNode> {
117	  const rootMetadata = {
118	    checkpoint_id: checkpoint.id,
119	    branch: 'main',
120	    sessions: checkpoint.sessions.map((s) => s.sessionId),
121	    token_usage: {},
122	  };
123	  const metaSha = await hashBlob(repoDir, JSON.stringify(rootMetadata, null, 2));
124	  const entries: Record<string, FileNode | DirNode> = { 'metadata.json': { kind: 'blob', sha: metaSha } };
125	  for (let n = 0; n < checkpoint.sessions.length; n += 1) {
126	    entries[String(n)] = await buildSessionNode(repoDir, checkpoint.sessions[n]!);
127	  }
128	  return { kind: 'tree', entries };
129	}
