131	/** Builds a temp git repo with one trailer-linked commit per checkpoint and checkpoint trees in the given layout. */
132	export async function makeRepo(spec: FixtureSpec): Promise<string> {
133	  const repoDir = await mkdtemp(join(tmpdir(), 'dailies-ingest-'));
134	  await run(repoDir, ['init', '-q', '-b', 'main']);
135	  await run(repoDir, ['config', 'user.name', 'fixture']);
136	  await run(repoDir, ['config', 'user.email', 'fixture@example.com']);
137	
138	  await writeFile(join(repoDir, 'README.md'), '# fixture\n');
139	  await run(repoDir, ['add', 'README.md']);
140	  await run(repoDir, ['commit', '-q', '-m', 'init']);
141	
142	  const branchNodes: { id: string; node: DirNode }[] = [];
143	
144	  for (const checkpoint of spec.checkpoints) {
145	    await writeFile(join(repoDir, `${checkpoint.id}.txt`), checkpoint.id);
146	    await run(repoDir, ['add', `${checkpoint.id}.txt`]);
147	    await run(repoDir, ['commit', '-q', '-m', `work for ${checkpoint.id}\n\nEntire-Checkpoint: ${checkpoint.id}`]);
148	
149	    const node = await buildCheckpointNode(repoDir, checkpoint);
150	
151	    if (spec.layout === 'refs') {
152	      const treeSha = await buildTree(repoDir, node.entries);
153	      const commitSha = await commitTree(repoDir, treeSha, `checkpoint ${checkpoint.id}`);
154	      const shard = checkpoint.id.slice(0, 2);
155	      await run(repoDir, ['update-ref', `refs/entire/checkpoints/${shard}/${checkpoint.id}`, commitSha]);
156	    } else {
157	      branchNodes.push({ id: checkpoint.id, node });
158	    }
159	  }
160	
161	  if (spec.layout === 'branch' && branchNodes.length > 0) {
162	    const rootEntries: Record<string, DirNode> = {};
163	    for (const { id, node } of branchNodes) {
164	      const shard = id.slice(0, 2);
165	      const rest = id.slice(2);
166	      const shardNode = (rootEntries[shard] ??= { kind: 'tree', entries: {} });
167	      shardNode.entries[rest] = node;
168	    }
169	    const treeSha = await buildTree(repoDir, rootEntries);
170	    const commitSha = await commitTree(repoDir, treeSha, 'checkpoints branch');
171	    await run(repoDir, ['update-ref', 'refs/heads/entire/checkpoints/v1', commitSha]);
172	  }
173	
174	  return repoDir;
175	}
